use std::fs
use std::env
use std::process

fn emit(text: string, number: bool, counter: int) -> int {
    if !number {
        print(text)
        return counter
    }
    if text.len() == 0 {
        return counter
    }
    let mut c = counter
    let ends = text.ends_with("\n")
    let parts: Vec<string> = text.split("\n").collect()
    let total: int = parts.len() as int
    let mut i: int = 0
    for p in parts {
        i += 1
        if i == total && ends {
            break
        }
        c += 1
        println("${c:>6}\t${p}")
    }
    c
}

fn main() {
    let mut number = false
    let mut names: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            names.push(a)
        }
    }
    let mut counter: int = 0
    let mut status: int = 0
    if names.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for n in names {
            match fs::read_to_string(n) {
                Ok(t) => { counter = emit(t, number, counter) }
                Err(_) => {
                    println("cat: ${n}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        process::exit(status)
    }
}

